FROM `Sales Orders` so
JOIN Products p ON so._ProductID = p.ProductID
WHERE (
    CAST(REPLACE(so.`Unit Price`, ',', '') AS REAL) -
    CAST(REPLACE(so.`Unit Cost`, ',', '') AS REAL)
) = (
    SELECT MAX(
        CAST(REPLACE(`Unit Price`, ',', '') AS REAL) -
        CAST(REPLACE(`Unit Cost`, ',', '') AS REAL)
    )
    FROM `Sales Orders`
);

